      <span className="text-xs font-medium tracking-wide text-slate-300">Tenorschreibhilfe</span>
      {(context || pdf || generated) ? <button type="button" onClick={reset} aria-label="Neu beginnen" className="text-slate-300 transition hover:text-slate-700"><RotateCcw className="size-4" /></button> : <span className="size-4" />}
    </header>

    {!generated ? <main className="mx-auto flex min-h-[calc(100vh-4rem)] max-w-4xl flex-col px-6 pb-28 pt-[8vh]">
      {pdf && <div className="mb-8 flex items-center gap-3 text-sm text-slate-500"><FileUp className="size-4" /><span className="truncate">{pdf.name}</span><span className="text-[10px] text-slate-300">lokal · noch ohne Texterkennung</span><button type="button" onClick={() => setPdf(null)} aria-label="PDF entfernen" className="ml-auto text-slate-300 hover:text-slate-700"><X className="size-4" /></button></div>}
      <div className="min-h-[calc(100vh-17rem)] w-full flex-1 cursor-text" onClick={() => contextInput.current?.focus()}>
        <textarea
          ref={contextInput}
          autoFocus
          value={context}
          onChange={(event) => { setContext(event.target.value); setGenerated(false); }}
          onKeyDown={(event) => { if (event.key === "Tab" && suggestion) { event.preventDefault(); acceptSuggestion(); } }}
          placeholder={pdf ? "" : "Beschreibe den Sachverhalt oder droppe ein PDF oder diktiere den Sachverhalt …"}
          aria-label="Sachverhalt oder Tenor"
          rows={1}
          className="block min-h-9 w-full resize-none overflow-hidden bg-transparent font-serif text-lg leading-[1.8] text-slate-800 outline-none placeholder:text-slate-300 sm:text-xl"
        />
        {needsMoreContext && <p className="mt-2 text-sm leading-6 text-slate-300">{contextQuestion}</p>}
        {suggestion && <button type="button" onClick={(event) => { event.stopPropagation(); acceptSuggestion(); }} className="mt-3 flex items-start gap-3 text-left text-sm leading-6 text-slate-300 transition hover:text-slate-500"><span className="mt-1 flex shrink-0 items-center gap-1 font-mono text-[10px] text-slate-400"><Keyboard className="size-3" />Tab</span><span>{suggestion.text.replace(/\s+/g, " ")}</span></button>}
      </div>

      <div className="fixed inset-x-0 bottom-0 z-20 border-t border-slate-100 bg-white/95 backdrop-blur">
        <div className="mx-auto flex min-h-20 max-w-4xl items-center justify-between px-6">
          <div className="flex items-center gap-1">
          <button type="button" onClick={() => fileInput.current?.click()} aria-label="PDF hochladen" className="rounded-full p-3 text-slate-300 transition hover:bg-slate-50 hover:text-slate-700"><FileUp className="size-5" /></button>
          <button type="button" onClick={toggleDictation} aria-label={dictating ? "Diktat beenden" : "Sachverhalt diktieren"} className={`rounded-full p-3 transition ${dictating ? "bg-red-50 text-red-500" : "text-slate-300 hover:bg-slate-50 hover:text-slate-700"}`}><Mic className="size-5" /></button>
          <input ref={fileInput} type="file" accept="application/pdf,.pdf" className="hidden" onChange={(event) => acceptPdf(event.target.files?.[0])} />
          {correctionMode && <span className="ml-2 text-[10px] uppercase tracking-wider text-slate-300">Tenor erkannt · Korrekturmodus</span>}
          {dictationNotice && <span className="ml-2 text-xs text-slate-400">{dictationNotice}</span>}
          </div>
          {canGenerate && <button type="button" onClick={generate} disabled={generating} className="flex items-center gap-2 rounded-full bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60">{generating ? <Loader2 className="size-4 animate-spin" /> : <Sparkles className="size-4" />}Generieren</button>}
        </div>
      </div>
    </main> : <main className="mx-auto max-w-6xl px-6 pb-16 pt-12">
      <h1 className="text-center font-sans text-sm font-medium text-slate-400">Wähle einen Entwurf</h1>
      <div className="mt-12 grid md:grid-cols-2 md:divide-x md:divide-slate-100">
        <DraftChoice title="Präzise" draft={preciseDraft} text={preciseText} selected={selected === "precise"} onSelect={() => setSelected("precise")} onText={setPreciseText} />
        <DraftChoice title="Technikneutral" draft={neutralDraft} text={neutralText} selected={selected === "neutral"} onSelect={() => setSelected("neutral")} onText={setNeutralText} />
      </div>
      {selected && <div className="mt-10 flex justify-center"><button type="button" onClick={adoptSelected} className="rounded-full bg-slate-950 px-6 py-3 text-sm font-semibold text-white">Entwurf übernehmen</button></div>}
    </main>}
  </div>;
}

