    : contextLength < 70
      ? "Was genau soll das Unternehmen künftig unterlassen?"
      : "Noch hilfreich: Wer ist betroffen und wurde der Verstoß bereits anderswo wiederholt?";

  useEffect(() => {
    if (!correctionMode || generated || context.trim().length < 4) { setSuggestion(null); return; }
    const timer = window.setTimeout(() => setSuggestion(nextAutofillBlock(profile, acceptedIds)), 800);
    return () => window.clearTimeout(timer);
  }, [acceptedIds, context, correctionMode, generated, profile]);

  useEffect(() => {
    const input = contextInput.current;
    if (!input) return;
    input.style.height = "0px";
    input.style.height = `${Math.max(input.scrollHeight, 36)}px`;
